INSERT INTO units(id,project_id,number,track_id,state,title,created_by_user,approved_revision,approved_at,created_at,updated_at) VALUES('00000000-0000-0000-0000-000000001001','00000000-0000-0000-0000-000000000010',1,'00000000-0000-0000-0000-000000000003','queued','Download fixture','00000000-0000-0000-0000-000000000001',1,'2001-01-01Z','2001-01-01Z','2001-01-01Z'),('00000000-0000-0000-0000-000000001002','00000000-0000-0000-0000-000000000011',1,'00000000-0000-0000-0000-000000000003','queued','Other fixture','00000000-0000-0000-0000-000000000001',1,'2001-01-01Z','2001-01-01Z','2001-01-01Z');
INSERT INTO attempts(id,project_id,unit_id,sequence,state,unit_revision,science_revision,track_id,claimed_by_user,via_channel,lease_generation,claimed_at,finished_at) SELECT ('00000000-0000-0000-0000-'||lpad((2000+n)::text,12,'0'))::uuid,('00000000-0000-0000-0000-'||lpad((9+n)::text,12,'0'))::uuid,('00000000-0000-0000-0000-'||lpad((1000+n)::text,12,'0'))::uuid,1,'failed',1,1,'00000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000001','historical',0,'2001-01-01Z','2001-01-02Z' FROM generate_series(1,2)n;
INSERT INTO artifacts(id,project_id,attempt_id,role,backend,bucket,key,size_bytes,sha256,media_type,verified_at,interface,content_validated) SELECT ('00000000-0000-0000-0000-'||lpad((3000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000002001',role,'local','fixture',CASE WHEN n=1 THEN 'hello.txt' ELSE 'hello-'||n||'.txt' END,5,repeat('a',64),'text/plain','2001-01-01Z',CASE WHEN role='data' THEN 'data' END,CASE WHEN role='data' THEN true END FROM (VALUES(1,'report_asset'),(2,'data'),(3,'logs')) AS r(n,role);
